  { id: 'test', cat: 'js', name: 'Мини-тест функции', desc: 'assert без библиотек', code: `function assert(condition, message) {\n  if (!condition) throw new Error('❌ ' + message);\n  console.log('✅ ' + message);\n}\nassert(add(2, 3) === 5, '2 + 3 = 5');` }
