export function mdnLink(term) {
  const key = DOCS[term]?.[1] || term;
  const path = /^[A-Z]/.test(key) ? `Web/JavaScript/Reference/Global_Objects/${key}` :
    ['img', 'button', 'main', 'a', 'form', 'input', 'nav', 'section'].includes(key) ? `Web/HTML/Element/${key}` :
    `Web/${key.includes('-') ? 'CSS/' : 'API/'}${key}`;
  return 'https://developer.mozilla.org/ru/docs/' + path;
}

